def convert_repeats_to_instances(apps, schema_editor):
    logger.info("Starting migration to convert repeats to individual episode instances")

    Episode = apps.get_model('app', 'Episode')
    HistoricalEpisode = apps.get_model('app', 'HistoricalEpisode')

    episodes_with_repeats = Episode.objects.filter(repeats__gt=0)
    logger.info("Found %d episodes with repeats to process", episodes_with_repeats.count())

    for episode in episodes_with_repeats:
        logger.info(
            "Processing %s S%02dE%02d (ID: %d) with %d repeats",
            episode.item.title,
            episode.item.season_number,
            episode.item.episode_number,
            episode.id,
            episode.repeats
        )

        history = HistoricalEpisode.objects.filter(
            id=episode.id
        ).order_by('history_date')
        logger.info(
            "Found %d historical records for episode ID %d",
            history.count(),
            episode.id
        )

        # Create new episodes for each historical record including the current one
        for historical_record in history:
            new_episode = Episode(
            item=episode.item,
            related_season=episode.related_season,
            end_date=historical_record.end_date,
            repeats=0
            )
            new_episode.save()

            HistoricalEpisode.objects.create(
                id=new_episode.id,
                history_date=historical_record.history_date,
                history_type='+',
                history_user=historical_record.history_user,
                end_date=historical_record.end_date,
                repeats=0,
            )
            logger.info(
                "Created new episode ID %d for historical record from %s",
                new_episode.id,
                historical_record.history_date
            )


        # Delete the original episode
        episode.delete()
        logger.info(
            "Deleted original episode ID %d with %d repeats",
        )
